export const SCHOOLS_LARGE: SchoolLite[] = [...UNIVERSITIES_R1, ...UNIVERSITIES_ADDITIONAL, ...UNIVERSITIES_EXPANDED, ...UNIVERSITIES_MEGA_1, ...UNIVERSITIES_MEGA_2, ...UNIVERSITIES_MEGA_3, ...UNIVERSITIES_MEGA_4, ...UNIVERSITIES_MEGA_5, ...UNIVERSITIES_MEGA_6, ...UNIVERSITIES_MEGA_7, ...STEM_HIGH_SCHOOLS, ...HIGH_SCHOOLS_EXPANDED];

export const getLargeSchoolBySlug = (slug: string) => SCHOOLS_LARGE.find((s) => s.slug === slug);
export const getAllLargeSchoolPaths = () => SCHOOLS_LARGE.map((s) => s.slug);
export const getUniversitiesByState = (state: string) => SCHOOLS_LARGE.filter((s) => s.stateAbbr === state && s.type === "university");
